ALTER TABLE expenses ADD COLUMN receiptNo TEXT NOT NULL DEFAULT '';
ALTER TABLE expenses ADD COLUMN transactionTime TEXT NOT NULL DEFAULT '';
UPDATE expenses SET category = CASE category WHEN '未指定' THEN 'Unspecified' WHEN '现金' THEN 'Cash' WHEN '电子钱包' THEN 'E-wallet' WHEN '信用卡' THEN 'Credit card' WHEN '借记卡' THEN 'Debit card' WHEN '银行转账' THEN 'Bank transfer' WHEN '预付／储值卡' THEN 'Prepaid card' WHEN '其他' THEN 'Other' WHEN '未分类' THEN 'Uncategorized' WHEN '餐饮' THEN 'Food & drinks' WHEN '交通' THEN 'Transport' WHEN '食品杂货' THEN 'Groceries' WHEN '购物' THEN 'Shopping' WHEN '居家账单' THEN 'Household bills' WHEN '医疗健康' THEN 'Health' WHEN '娱乐旅行' THEN 'Leisure & travel' WHEN '手动' THEN 'Manual' WHEN '分享文字' THEN 'Shared text' WHEN '分享文件' THEN 'Shared file' WHEN '分享图片' THEN 'Shared image' WHEN '分享 PDF' THEN 'Shared PDF' ELSE category END;
UPDATE expenses SET method = CASE method WHEN '未指定' THEN 'Unspecified' WHEN '现金' THEN 'Cash' WHEN '电子钱包' THEN 'E-wallet' WHEN '信用卡' THEN 'Credit card' WHEN '借记卡' THEN 'Debit card' WHEN '银行转账' THEN 'Bank transfer' WHEN '预付／储值卡' THEN 'Prepaid card' WHEN '其他' THEN 'Other' WHEN '未分类' THEN 'Uncategorized' WHEN '餐饮' THEN 'Food & drinks' WHEN '交通' THEN 'Transport' WHEN '食品杂货' THEN 'Groceries' WHEN '购物' THEN 'Shopping' WHEN '居家账单' THEN 'Household bills' WHEN '医疗健康' THEN 'Health' WHEN '娱乐旅行' THEN 'Leisure & travel' WHEN '手动' THEN 'Manual' WHEN '分享文字' THEN 'Shared text' WHEN '分享文件' THEN 'Shared file' WHEN '分享图片' THEN 'Shared image' WHEN '分享 PDF' THEN 'Shared PDF' ELSE method END;
UPDATE expenses SET source = CASE source WHEN '未指定' THEN 'Unspecified' WHEN '现金' THEN 'Cash' WHEN '电子钱包' THEN 'E-wallet' WHEN '信用卡' THEN 'Credit card' WHEN '借记卡' THEN 'Debit card' WHEN '银行转账' THEN 'Bank transfer' WHEN '预付／储值卡' THEN 'Prepaid card' WHEN '其他' THEN 'Other' WHEN '未分类' THEN 'Uncategorized' WHEN '餐饮' THEN 'Food & drinks' WHEN '交通' THEN 'Transport' WHEN '食品杂货' THEN 'Groceries' WHEN '购物' THEN 'Shopping' WHEN '居家账单' THEN 'Household bills' WHEN '医疗健康' THEN 'Health' WHEN '娱乐旅行' THEN 'Leisure & travel' WHEN '手动' THEN 'Manual' WHEN '分享文字' THEN 'Shared text' WHEN '分享文件' THEN 'Shared file' WHEN '分享图片' THEN 'Shared image' WHEN '分享 PDF' THEN 'Shared PDF' ELSE source END;
UPDATE accounts SET method = CASE method WHEN '未指定' THEN 'Unspecified' WHEN '现金' THEN 'Cash' WHEN '电子钱包' THEN 'E-wallet' WHEN '信用卡' THEN 'Credit card' WHEN '借记卡' THEN 'Debit card' WHEN '银行转账' THEN 'Bank transfer' WHEN '预付／储值卡' THEN 'Prepaid card' WHEN '其他' THEN 'Other' WHEN '未分类' THEN 'Uncategorized' WHEN '餐饮' THEN 'Food & drinks' WHEN '交通' THEN 'Transport' WHEN '食品杂货' THEN 'Groceries' WHEN '购物' THEN 'Shopping' WHEN '居家账单' THEN 'Household bills' WHEN '医疗健康' THEN 'Health' WHEN '娱乐旅行' THEN 'Leisure & travel' WHEN '手动' THEN 'Manual' WHEN '分享文字' THEN 'Shared text' WHEN '分享文件' THEN 'Shared file' WHEN '分享图片' THEN 'Shared image' WHEN '分享 PDF' THEN 'Shared PDF' ELSE method END;
